static Str dwarf_name_find(const DwarfName *t, Int n, uint32_t v) {
    Int lo = 0;
    Int hi = n;
    while (lo < hi) {
        Int mid = lo + (hi - lo) / 2;
        if (t[mid].v < v)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < n && t[lo].v == v)
        return t[lo].name;
    return BURROW_STR_EMPTY;
}

Str burrow__dwarf_attr_name(DwarfAttr a) {
    return dwarf_name_find(dwarf_attr_names,
                           (Int)(sizeof dwarf_attr_names / sizeof dwarf_attr_names[0]),
                           a);
}

Str burrow__dwarf_tag_name(DwarfTag t) {
    return dwarf_name_find(
        dwarf_tag_names, (Int)(sizeof dwarf_tag_names / sizeof dwarf_tag_names[0]), t);
}
